(function() {
    'use strict';

    class CleanSlateAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'CleanSlate: AML Compliance';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    title: 'Round 1: Baseline Assessment and Triage',
                    description: 'You inherit Castellan Bank after two OCC Matters Requiring Attention. The alert backlog stands at 1,200 unreviewed items. The OCC expects backlog clearance within 60 days while maintaining monitoring coverage.<br><br>Default TMS settings represent the pre-examination configuration the OCC already found inadequate. Improve coverage without overwhelming your 80 analyst-hours of investigation capacity.',
                    event: 'CTR Processing Error: A data quality issue caused 60 CTRs from last quarter to be filed with incorrect amounts. Prioritise correction and voluntary self-disclosure to FinCEN.',
                    structuringEmbedded: 10,
                    layeringEmbedded: 4,
                    tbmlEmbedded: 3,
                    digitalEmbedded: 2,
                    structuringDifficulty: 4,
                    layeringDifficulty: 5,
                    tbmlDifficulty: 7,
                    digitalDifficulty: 6,
                    structuringAlertBase: 7,
                    wireAlertBase: 5,
                    anomalyAlertBase: 9,
                    digitalAlertBase: 3,
                    tradeAlertBase: 12,
                    capacityBonus: 0
                },
                {
                    title: 'Round 2: Typology Escalation',
                    description: 'The OCC issues guidance requiring improved correspondent banking monitoring for four Florida correspondents with elevated cash-intensive business risk.<br><br>First structuring sequences and layering chains appear. Review Round 1 false positive breakdown and adjust rules to reduce noise in low-risk segments while increasing sensitivity in correspondent channels.',
                    event: '314(a) Information Request: FinCEN asks whether Castellan holds accounts for an individual under federal investigation. You have 2 weeks to respond. A senior analyst has also resigned, reducing capacity by 8 hours this round.',
                    structuringEmbedded: 12,
                    layeringEmbedded: 5,
                    tbmlEmbedded: 3,
                    digitalEmbedded: 2,
                    structuringDifficulty: 5,
                    layeringDifficulty: 6,
                    tbmlDifficulty: 7,
                    digitalDifficulty: 7,
                    structuringAlertBase: 8,
                    wireAlertBase: 6,
                    anomalyAlertBase: 10,
                    digitalAlertBase: 4,
                    tradeAlertBase: 14,
                    capacityBonus: -8
                },
                {
                    title: 'Round 3: Complexity and Interconnection',
                    description: 'Typologies now span multiple business lines and appear commercially legitimate. A layering chain connects Wealth Management and Correspondent Banking divisions. The OCC advances the examination date by two weeks.<br><br>FIU escalation becomes critical for multi-division cases. TBML patterns require trade finance documentation review to detect.',
                    event: 'Law Enforcement Referral: A federal agency contacts Castellan informally about a commercial client suspected of TBML. No SAR is yet on file. Additionally, a crypto exchange client is receiving dramatically increased wire volumes from multiple international jurisdictions.',
                    structuringEmbedded: 8,
                    layeringEmbedded: 5,
                    tbmlEmbedded: 4,
                    digitalEmbedded: 3,
                    structuringDifficulty: 6,
                    layeringDifficulty: 7,
                    tbmlDifficulty: 8,
                    digitalDifficulty: 8,
                    structuringAlertBase: 8,
                    wireAlertBase: 7,
                    anomalyAlertBase: 11,
                    digitalAlertBase: 5,
                    tradeAlertBase: 15,
                    capacityBonus: 0
                },
                {
                    title: 'Round 4: Regulatory Examination',
                    description: 'The OCC examination begins. You receive the examination workprogram with document requests and evaluation criteria. Manage the final month of transactions while preparing examination materials.<br><br>Several alerts are borderline SAR decisions. Weigh the risk of defensive over-filing against the risk of missing genuine suspicious activity during the examination period.',
                    event: 'OCC Document Request: The examination team requests a complete SAR inventory, investigation files, and TMS configuration history for the past 12 months. A financial journalist also inquires whether Castellan has filed SARs on a publicly named individual. SAR confidentiality rules apply.',
                    structuringEmbedded: 10,
                    layeringEmbedded: 4,
                    tbmlEmbedded: 4,
                    digitalEmbedded: 3,
                    structuringDifficulty: 7,
                    layeringDifficulty: 8,
                    tbmlDifficulty: 9,
                    digitalDifficulty: 9,
                    structuringAlertBase: 9,
                    wireAlertBase: 7,
                    anomalyAlertBase: 12,
                    digitalAlertBase: 5,
                    tradeAlertBase: 16,
                    capacityBonus: 0
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    rcs: 0,
                    detectionRate: 0,
                    falsePositiveRate: 0,
                    sarAccuracy: 0,
                    sarQuality: 0,
                    investigationCompletion: 0,
                    kycProgress: 0,
                    backlogRemaining: 1200,
                    kycCompleted: 0,
                    totalDetected: 0,
                    totalEmbedded: 0,
                    totalAlerts: 0,
                    totalFalsePositives: 0,
                    totalSarsFiled: 0,
                    totalCorrectSars: 0,
                    totalInvestigated: 0,
                    totalGenerated: 0,
                    cumulativeSarQuality: 0,
                    rcsHistory: [],
                    detectionHistory: [],
                    fpHistory: [],
                    sarQualityHistory: [],
                    completionHistory: [],
                    backlogHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    structuringSensitivity: 3,
                    wireSensitivity: 3,
                    anomalySensitivity: 3,
                    digitalSensitivity: 3,
                    tradeFinanceEnabled: 0,
                    backlogPct: 40
                };
            }
            this._updateBriefing(state);
            this._setupSliderListeners();
        }

        _setupSliderListeners() {
            var self = this;
            var sliders = [
                { id: 'structuringInput', display: 'structuringValue', suffix: '' },
                { id: 'wireInput', display: 'wireValue', suffix: '' },
                { id: 'anomalyInput', display: 'anomalyValue', suffix: '' },
                { id: 'digitalInput', display: 'digitalValue', suffix: '' },
                { id: 'backlogInput', display: 'backlogAllocValue', suffix: '%' }
            ];
            sliders.forEach(function(s) {
                var el = document.getElementById(s.id);
                var disp = document.getElementById(s.display);
                if (el && disp) {
                    el.addEventListener('input', function() {
                        disp.textContent = el.value + s.suffix;
                        self._updateProjection();
                    });
                }
            });
            var tfEl = document.getElementById('tradeFinanceInput');
            if (tfEl) {
                tfEl.addEventListener('change', function() {
                    self._updateProjection();
                });
            }
            setTimeout(function() { self._updateProjection(); }, 300);
        }

        _updateProjection() {
            var roundIdx = 0;
            if (window.mySimulation && window.mySimulation.state) {
                roundIdx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, 3);
            }
            var round = this.ROUNDS[roundIdx];
            var s1 = parseFloat(document.getElementById('structuringInput')?.value || 3);
            var s2 = parseFloat(document.getElementById('wireInput')?.value || 3);
            var s3 = parseFloat(document.getElementById('anomalyInput')?.value || 3);
            var s4 = parseFloat(document.getElementById('digitalInput')?.value || 3);
            var tf = document.getElementById('tradeFinanceInput')?.checked ? 1 : 0;
            var bp = parseFloat(document.getElementById('backlogInput')?.value || 40);

            var alerts = Math.round(s1 * round.structuringAlertBase + s2 * round.wireAlertBase + s3 * round.anomalyAlertBase + s4 * round.digitalAlertBase + tf * round.tradeAlertBase);
            var capacity = 80 + round.capacityBonus;
            var availHours = Math.round(capacity * (1 - bp / 100));

            var projEl = document.getElementById('projectedAlerts');
            var availEl = document.getElementById('availableHours');
            if (projEl) projEl.textContent = alerts;
            if (availEl) availEl.textContent = availHours + 'h';
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = '<strong>' + round.title + '</strong><br><br>' + round.description;
            var eventEl = document.getElementById('eventCard');
            if (eventEl) {
                eventEl.innerHTML = '<strong>Event:</strong> ' + round.event;
                eventEl.style.display = 'block';
            }
        }

        validateDecisions(decisions) {
            var s1El = document.getElementById('structuringInput');
            var s2El = document.getElementById('wireInput');
            var s3El = document.getElementById('anomalyInput');
            var s4El = document.getElementById('digitalInput');
            var tfEl = document.getElementById('tradeFinanceInput');
            var bpEl = document.getElementById('backlogInput');

            if (s1El) decisions.structuringSensitivity = parseInt(s1El.value);
            if (s2El) decisions.wireSensitivity = parseInt(s2El.value);
            if (s3El) decisions.anomalySensitivity = parseInt(s3El.value);
            if (s4El) decisions.digitalSensitivity = parseInt(s4El.value);
            if (tfEl) decisions.tradeFinanceEnabled = tfEl.checked ? 1 : 0;
            if (bpEl) decisions.backlogPct = parseInt(bpEl.value);

            var totalSensitivity = decisions.structuringSensitivity + decisions.wireSensitivity + decisions.anomalySensitivity + decisions.digitalSensitivity;
            if (totalSensitivity < 4) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('sensitivity_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var totalCapacity = 80 + round.capacityBonus;
            var backlogHours = totalCapacity * (d.backlogPct / 100);
            var currentHours = totalCapacity - backlogHours;

            var structuringAlerts = Math.round(d.structuringSensitivity * round.structuringAlertBase);
            var wireAlerts = Math.round(d.wireSensitivity * round.wireAlertBase);
            var anomalyAlerts = Math.round(d.anomalySensitivity * round.anomalyAlertBase);
            var digitalAlerts = Math.round(d.digitalSensitivity * round.digitalAlertBase);
            var tradeAlerts = d.tradeFinanceEnabled ? round.tradeAlertBase : 0;
            var totalAlerts = structuringAlerts + wireAlerts + anomalyAlerts + digitalAlerts + tradeAlerts;

            var structDetect = Math.min(round.structuringEmbedded, Math.round(round.structuringEmbedded * Math.min(1, d.structuringSensitivity / round.structuringDifficulty)));
            var wireDetect = Math.min(round.layeringEmbedded, Math.round(round.layeringEmbedded * Math.min(1, d.wireSensitivity / round.layeringDifficulty)));
            var anomalyBonus = Math.round((structDetect + wireDetect) * 0.1 * Math.min(1, d.anomalySensitivity / 6));
            var digitalDetect = Math.min(round.digitalEmbedded, Math.round(round.digitalEmbedded * Math.min(1, d.digitalSensitivity / round.digitalDifficulty)));
            var tradeDetect = d.tradeFinanceEnabled ? Math.min(round.tbmlEmbedded, Math.round(round.tbmlEmbedded * Math.min(1, 0.7 + d.anomalySensitivity * 0.03))) : 0;
            var totalDetected = structDetect + wireDetect + anomalyBonus + digitalDetect + tradeDetect;
            var totalEmbedded = round.structuringEmbedded + round.layeringEmbedded + round.tbmlEmbedded + round.digitalEmbedded;
            totalDetected = Math.min(totalDetected, totalEmbedded);

            var detectionRate = totalEmbedded > 0 ? Math.round((totalDetected / totalEmbedded) * 100) : 0;

            var falsePositives = Math.max(0, totalAlerts - totalDetected);
            var fpRate = totalAlerts > 0 ? Math.round((falsePositives / totalAlerts) * 100) : 0;

            var avgHoursPerAlert = 1.5;
            var alertsInvestigated = Math.min(totalAlerts, Math.floor(currentHours / avgHoursPerAlert));
            var alertsAbandoned = totalAlerts - alertsInvestigated;
            var completionRate = totalAlerts > 0 ? Math.round((alertsInvestigated / totalAlerts) * 100) : 100;

            var sarsFiled = totalDetected;
            var sarAccuracy = totalDetected > 0 ? Math.round((totalDetected / Math.max(totalDetected, sarsFiled)) * 100) : 0;

            var timePerInvestigation = alertsInvestigated > 0 ? currentHours / alertsInvestigated : 0;
            var sarQualityRaw = Math.min(5, 1 + timePerInvestigation * 0.9);
            var sarQuality = Math.round(sarQualityRaw * 10) / 10;

            var backlogCleared = Math.min(state.domainState.backlogRemaining, Math.floor(backlogHours * 2));
            state.domainState.backlogRemaining = Math.max(0, state.domainState.backlogRemaining - backlogCleared);

            var kycThisRound = Math.round(25 * (1 - d.backlogPct / 200));
            kycThisRound = Math.min(kycThisRound, 340 - state.domainState.kycCompleted);
            state.domainState.kycCompleted += kycThisRound;
            var kycProgress = Math.round((state.domainState.kycCompleted / 340) * 100);

            state.domainState.totalDetected += totalDetected;
            state.domainState.totalEmbedded += totalEmbedded;
            state.domainState.totalAlerts += totalAlerts;
            state.domainState.totalFalsePositives += falsePositives;
            state.domainState.totalSarsFiled += sarsFiled;
            state.domainState.totalCorrectSars += totalDetected;
            state.domainState.totalInvestigated += alertsInvestigated;
            state.domainState.totalGenerated += totalAlerts;
            state.domainState.cumulativeSarQuality += sarQuality;

            var cumDetection = state.domainState.totalEmbedded > 0 ? (state.domainState.totalDetected / state.domainState.totalEmbedded) * 100 : 0;
            var cumFP = state.domainState.totalAlerts > 0 ? (state.domainState.totalFalsePositives / state.domainState.totalAlerts) * 100 : 0;
            var cumSarAcc = state.domainState.totalSarsFiled > 0 ? (state.domainState.totalCorrectSars / state.domainState.totalSarsFiled) * 100 : 0;
            var cumSarQual = state.domainState.cumulativeSarQuality / state.currentPeriod;
            var cumCompletion = state.domainState.totalGenerated > 0 ? (state.domainState.totalInvestigated / state.domainState.totalGenerated) * 100 : 100;

            var detectionScore = Math.min(100, cumDetection / 75 * 100);
            var fpScore = cumFP <= 85 ? 100 : Math.max(0, 100 - (cumFP - 85) * 6.67);
            var sarAccScore = Math.min(100, cumSarAcc / 70 * 100);
            var sarQualScore = Math.min(100, (cumSarQual / 3.5) * 100);
            var completionScore = Math.min(100, cumCompletion / 90 * 100);
            var kycScore = Math.min(100, kycProgress / 75 * 100);

            var rcs = Math.round(
                detectionScore * 0.25 +
                fpScore * 0.15 +
                sarAccScore * 0.20 +
                sarQualScore * 0.20 +
                completionScore * 0.10 +
                kycScore * 0.10
            );

            state.domainState.rcs = rcs;
            state.domainState.detectionRate = Math.round(cumDetection);
            state.domainState.falsePositiveRate = Math.round(cumFP);
            state.domainState.sarAccuracy = Math.round(cumSarAcc);
            state.domainState.sarQuality = Math.round(cumSarQual * 10) / 10;
            state.domainState.investigationCompletion = Math.round(cumCompletion);
            state.domainState.kycProgress = kycProgress;

            state.domainState.rcsHistory.push(rcs);
            state.domainState.detectionHistory.push(detectionRate);
            state.domainState.fpHistory.push(fpRate);
            state.domainState.sarQualityHistory.push(sarQuality);
            state.domainState.completionHistory.push(completionRate);
            state.domainState.backlogHistory.push(state.domainState.backlogRemaining);

            var _cr = state.currentPeriod;
            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: _cr + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                totalAlerts: totalAlerts,
                totalDetected: totalDetected,
                totalEmbedded: totalEmbedded,
                detectionRate: detectionRate,
                fpRate: fpRate,
                alertsInvestigated: alertsInvestigated,
                alertsAbandoned: alertsAbandoned,
                completionRate: completionRate,
                sarsFiled: sarsFiled,
                sarQuality: sarQuality,
                backlogCleared: backlogCleared,
                backlogRemaining: state.domainState.backlogRemaining,
                kycRefreshed: kycThisRound,
                kycProgress: kycProgress,
                rcs: rcs
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('rcsDisplay', 'domainState.rcs', function(v) { return Math.round(v); });
            uiManager.bind('detectionDisplay', 'domainState.detectionRate', function(v) { return Math.round(v) + '%'; });
            uiManager.bind('fpDisplay', 'domainState.falsePositiveRate', function(v) { return Math.round(v) + '%'; });
            uiManager.bind('backlogDisplay', 'domainState.backlogRemaining', function(v) { return Math.round(v).toLocaleString(); });
            uiManager.bind('capacityDisplay', 'domainState.investigationCompletion', function(v) { return Math.round(v) + '%'; });
            uiManager.bind('kycDisplay', 'domainState.kycProgress', function(v) { return Math.round(v) + '%'; });
        }

        getChartConfig() {
            return {
                metricsChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Detection Rate (%)',
                                data: [],
                                borderColor: '#00e676',
                                backgroundColor: 'rgba(0,230,118,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'False Positive Rate (%)',
                                data: [],
                                borderColor: '#ff5252',
                                backgroundColor: 'rgba(255,82,82,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'SAR Quality (x20)',
                                data: [],
                                borderColor: '#ffab40',
                                backgroundColor: 'rgba(255,171,64,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Key Performance Metrics by Round', color: '#e0e0e0' },
                            legend: { labels: { color: '#b0b0b0' } }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, ticks: { color: '#888' }, grid: { color: 'rgba(255,255,255,0.05)' } },
                            x: { ticks: { color: '#888' }, grid: { color: 'rgba(255,255,255,0.05)' } }
                        }
                    }
                },
                rcsChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Regulatory Compliance Score',
                            data: [],
                            backgroundColor: [
                                'rgba(0,210,255,0.6)',
                                'rgba(0,210,255,0.6)',
                                'rgba(0,210,255,0.6)',
                                'rgba(0,210,255,0.6)'
                            ],
                            borderColor: '#00d2ff',
                            borderWidth: 2,
                            borderRadius: 8
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Regulatory Compliance Score', color: '#e0e0e0' },
                            legend: { labels: { color: '#b0b0b0' } }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, ticks: { color: '#888' }, grid: { color: 'rgba(255,255,255,0.05)' } },
                            x: { ticks: { color: '#888' }, grid: { color: 'rgba(255,255,255,0.05)' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.rcsHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                metricsChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.detectionHistory },
                        { data: state.domainState.fpHistory },
                        { data: state.domainState.sarQualityHistory.map(function(v) { return Math.round(v * 20); }) }
                    ]
                },
                rcsChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.rcsHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = history[history.length - 1].domainState || {};
            var finalRCS = ds.rcs || 0;
            var outcome = '';
            var insights = [];

            if (finalRCS >= 80) {
                outcome = 'MRA Closure with Commendation';
                insights.push('Outstanding compliance programme remediation. Both MRAs closed with commendation.');
                insights.push('OCC recommends no further targeted reviews for 18 months.');
            } else if (finalRCS >= 65) {
                outcome = 'MRA Closure';
                insights.push('Both MRAs closed. Examination report notes areas for continued improvement.');
                insights.push('Standard 12-month monitoring schedule maintained.');
            } else if (finalRCS >= 50) {
                outcome = 'Partial MRA Closure with New Finding';
                insights.push('Monitoring coverage MRA closed but SAR quality MRA remains open.');
                insights.push('New MRA issued for investigation documentation quality.');
            } else if (finalRCS >= 35) {
                outcome = 'Formal Memorandum of Understanding';
                insights.push('OCC determines remediation insufficient. Formal MOU issued.');
                insights.push('Quarterly OCC oversight meetings and third-party compliance review required.');
            } else {
                outcome = 'Cease and Desist Order';
                insights.push('OCC issues formal Cease and Desist Order.');
                insights.push('Correspondent banking restrictions and Board governance restructuring required.');
            }

            if ((ds.detectionRate || 0) < 60) insights.push('Detection rate was below minimum threshold. Consider increasing monitoring sensitivity for key typologies.');
            if ((ds.falsePositiveRate || 0) > 90) insights.push('False positive rate exceeded 90%. Rule calibration needs refinement to reduce analyst burden.');
            if ((ds.kycProgress || 0) < 50) insights.push('KYC refresh progress was insufficient. Overdue account reviews create significant regulatory exposure.');

            return {
                rcs: finalRCS,
                outcome: outcome,
                detectionRate: ds.detectionRate || 0,
                falsePositiveRate: ds.falsePositiveRate || 0,
                sarQuality: ds.sarQuality || 0,
                kycProgress: ds.kycProgress || 0,
                performance: outcome,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.alertsAbandoned > 0) {
                return window.mySimulation.t('hint_abandoned');
            }
            if (results.detectionRate < 50) {
                return window.mySimulation.t('hint_low_detection');
            }
            if (results.fpRate > 92) {
                return window.mySimulation.t('hint_high_fp');
            }
            if (results.sarQuality < 2.5) {
                return window.mySimulation.t('hint_low_sar_quality');
            }
            if (state.domainState.backlogRemaining > 600 && state.currentPeriod >= 2) {
                return window.mySimulation.t('hint_backlog');
            }
            if (results.detectionRate >= 75 && results.fpRate <= 85) {
                return window.mySimulation.t('hint_good');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.totalAlerts', label: 'Alerts', i18nKey: 'col_alerts' },
                { key: 'results.totalDetected', label: 'Detected', i18nKey: 'col_detected' },
                { key: 'results.detectionRate', label: 'Detect %', i18nKey: 'col_detection', formatter: function(v) { return v + '%'; } },
                { key: 'results.fpRate', label: 'FP %', i18nKey: 'col_fp', formatter: function(v) { return v + '%'; } },
                { key: 'results.alertsInvestigated', label: 'Investigated', i18nKey: 'col_investigated' },
                { key: 'results.sarsFiled', label: 'SARs Filed', i18nKey: 'col_sars' },
                { key: 'results.sarQuality', label: 'SAR Qual', i18nKey: 'col_sar_quality', formatter: function(v) { return v + '/5'; } },
                { key: 'results.backlogRemaining', label: 'Backlog', i18nKey: 'col_backlog' },
                { key: 'results.rcs', label: 'RCS', i18nKey: 'col_rcs' }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title: `CleanSlate: AML Compliance`,
                    subtitle: `Castellan Bank N.A. - Financial Crime Compliance Committee`,
                    period_label: `Round`,
                    period_of: `of`,
                    briefing_heading: `Regulatory Briefing`,
                    rcs_label: `Compliance Score`,
                    detection_label: `Detection Rate`,
                    fp_label: `False Positive Rate`,
                    backlog_label: `Alert Backlog`,
                    capacity_label: `Investigation Rate`,
                    kyc_label: `KYC Progress`,
                    decisions_heading: `TMS Configuration`,
                    structuring_label: `Cash Structuring Detector (1-10)`,
                    wire_label: `Wire Velocity Monitor (1-10)`,
                    anomaly_label: `Behavior Deviation Scorer (1-10)`,
                    digital_label: `Digital Asset Gateway Monitor (1-10)`,
                    trade_label: `Enable Trade Finance Documentation Review`,
                    backlog_alloc_label: `Backlog Allocation (% of analyst hours)`,
                    projected_alerts: `Projected New Alerts:`,
                    available_hours: `Available Investigation Hours:`,
                    submit_btn: `Submit Round`,
                    undo_btn: `Undo Last Round`,
                    history_heading: `Round History`,
                    sensitivity_warning: `Total monitoring sensitivity must be at least 4. Increase at least one monitor.`,
                    hint_abandoned: `Alerts were abandoned due to capacity constraints. This generates negative regulatory log entries. Consider reducing alert volume or backlog allocation.`,
                    hint_low_detection: `Detection rate is below 50%. The OCC will flag inadequate monitoring coverage. Increase sensitivity on monitors aligned with active typologies.`,
                    hint_high_fp: `False positive rate exceeds 92%. Alert fatigue degrades investigation quality. Consider reducing sensitivity on high-volume, low-yield monitors.`,
                    hint_low_sar_quality: `SAR narrative quality is low. Investigators need more time per alert. Reduce alert volume or increase investigation capacity allocation.`,
                    hint_backlog: `The alert backlog is still substantial. The OCC expects clearance within 60 days. Consider increasing backlog allocation.`,
                    hint_good: `Strong performance this round. Detection rate and false positive rate are both within target ranges.`,
                    col_alerts: `Alerts`,
                    col_detected: `Detected`,
                    col_detection: `Detect %`,
                    col_fp: `FP %`,
